{"command":"$script = @'
$ErrorActionPreference = 'Stop'
$stdout = Join-Path (Get-Location) '.tura-dev-hydration.out.log'
$stderr = Join-Path (Get-Location) '.tura-dev-hydration.err.log'
Remove-Item $stdout,$stderr -ErrorAction SilentlyContinue
$p = Start-Process -FilePath 'npm.cmd' -ArgumentList @('run','dev','--','--port','3012') -WorkingDirectory (Get-Location) -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru -WindowStyle Hidden
try {
  $ready = $false
  for ($i=0; $i -lt 60; $i++) {
    if ($p.HasExited) { throw "server exited $($p.ExitCode)" }
    try { $r = Invoke-WebRequest -Uri 'http://127.0.0.1:3012/' -UseBasicParsing -TimeoutSec 1; if ($r.StatusCode -eq 200) { $ready = $true; break } } catch {}
    Start-Sleep -Milliseconds 500
  }
  if (-not $ready) { throw 'server not ready' }
  @"
import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage();
page.on('console', msg => console.log('CONSOLE', msg.type(), msg.text()));
page.on('pageerror', err => console.log('PAGEERROR', err.message));
await page.goto('http://127.0.0.1:3012/', { waitUntil: 'networkidle' });
console.log('scripts', await page.locator('script').evaluateAll(s => s.map(x => x.src || x.textContent?.slice(0,50))));
console.log('hasReact', await page.evaluate(() => !!window.__REACT_DEVTOOLS_GLOBAL_HOOK__));
const tile = page.locator('.tile').nth(1);
await tile.hover();
await tile.getByRole('button', { name: 'Save' }).click({ force: true });
await page.waitForTimeout(1000);
console.log('status', await page.getByRole('status').innerText());
await browser.close();
"@ | Set-Content -Path '.tura-hydration-check.mjs'
  node .tura-hydration-check.mjs
} finally {
  if (-not $p.HasExited) { Stop-Process -Id $p.Id -Force }
}
'@; Set-Content -Path .tura\script-hydration-check.ps1 -Value $script; powershell -NoProfile -ExecutionPolicy Bypass -File .tura\script-hydration-check.ps1","workdir":"C:\Users\liuliu\Documents\tura_workspace\target\project-rebuild-makeup-tanstack-fullstack\matrix5-gpt55-medium-default-20260708-183126-prompt-gallery-fullstack-r2\projects\makeup-tura-balanced","timeout_ms":80000}

